SourceCode.Declaration:
/// <summary>
/// Custom helper class for frequently used functions
/// </summary>
class METHelper
{
}

Method.Source:
    /// <summary>
    /// Gets dimension value
    /// </summary>
    /// <param name = "_defaultDimension">RecId of default dimension</param>
    /// <param name = "_dimensionName">Dimension name</param>
    /// <returns>Returns dimension value</returns>
    public static DimensionValue getDimensionValue(RecId _defaultDimension, Name _dimensionName)
    {
        DimensionAttributeValueSetStorage dimStorage;
        ;

        dimStorage = DimensionAttributeValueSetStorage::find(_defaultDimension);

        return dimStorage.getDisplayValueByDimensionAttribute(DimensionAttribute::findByName(_dimensionName).RecId);
    }

    /// <summary>
    /// Returns word
    /// </summary>
    /// <param name = "_num">Number</param>
    /// <returns>String</returns>
    public static str getWord(str _num)
    {
        str ret;

        switch(_num)
        {
            case "@MET:ret1": ret = "@SYS26620"; break;
            case "@MET:Ret2": ret = "@SYS26621"; break;
            case "@MET:Ret3": ret = "@SYS26622"; break;
            case "@MET:Ret4": ret = "@SYS26626"; break;
            case "@MET:Ret5": ret = "@SYS26627"; break;
            case "@MET:Ret6": ret = "@SYS26628"; break;
            case "@MET:Ret7": ret = "@SYS26629"; break;
            case "@MET:Ret8": ret = "@SYS26630"; break;
            case "@MET:Ret9": ret = "@SYS26631"; break;
            default: ret = "@SYS2068"; break;

        }
        return ret;
    }
